import{z as A,x as i,o as B,c as d,q as s,j as r,D as e,d as E,s as l,S as o,b as t}from"./chunks/framework.C8m1ZpeB.js";const L=JSON.parse('{"title":"硬件页表游走","description":"","frontmatter":{"title":"硬件页表游走","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/hw-page-walk.md","filePath":"cs/hw-page-walk.md","lastUpdated":1791063341000}'),p={name:"cs/hw-page-walk.md"};function c(D,a,T,h,m,C){const n=i("Mermaid");return B(),d("div",null,[a[2]||(a[2]=s('<h1 id="硬件页表游走" tabindex="-1">硬件页表游走 <a class="header-anchor" href="#硬件页表游走" aria-label="Permalink to &quot;硬件页表游走&quot;">​</a></h1><div class="epigraph"><p>TLB 缺失不必陷入内核：MMU 按根指针自己走多级表，把叶项填进 TLB，只有真正缺页才陷阱。</p><footer>—— 据 Hennessy and Patterson, Computer Architecture: A Quantitative Approach；Patterson and Hennessy, Computer Organization and Design (RISC-V) 整理</footer></div><p><a href="/cs/multi-level-page-table">上一课</a>把 VPN 切段、逐级索引，并说硬件或软件都可以走这棵树。<a href="/cs/tlb-translate">TLB</a> 把缺失写成「查页表填 TLB」，未钉是谁查。本课不重讲三级切分。缺口是硬件页表游走：状态机从 <code>satp</code>/<code>CR3</code> 一类根寄存器出发，发出若干次普通访存，成功则填 TLB，项无效才精确异常。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>软件游走：TLB 缺失陷入，内核用特权 load 自己读页表再 <code>sfence</code>/<code>invlpg</code>。灵活，但路径长，且要处理「走表时再缺页」的嵌套。硬件游走：MMU 在当前特权下发物理（或经允许的虚拟）访问读各级项。缺口不是新的页表格式，而是<strong>把走表从陷阱热路径里拿掉</strong>，让 TLB 缺失更像一次短的 cache 缺失串。</p><p><span class="marginnote">「精确异常」翻译成大白话：异常发生时，异常指令之前的一切都已完成、之后的一切都未生效，机器状态干净得像那条指令恰好停住。走表若在中间出错，报告的仍是「那条用户访存指令」缺页——不是 MMU 内部某一步出了岔子。</span></p><p>走表访存自己走数据 cache，吃局部性；根和上层目录常热。</p><p><span class="marginnote">x86 长期硬件游走；RISC-V 允许实现选硬件或软件。教学主干取硬件游走，与精确异常衔接更直。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>TLB 缺失：锁存 VA，从根 PPN 起，按 VPN 段读描述符。有效且指向下一级则继续；叶项有效则把 VPN→PPN 与权限填入 TLB，重放那次 load/store。任一级无效、或权限在当前特权失败：按<a href="/cs/pipeline-exception">流水线异常</a>报告缺页或保护错，EPC 指向那条访存指令，不指向「假想的走表微指令」。</p><p><span class="marginnote">数字实例：RISC-V Sv39 把 39 位 VA 切成三个 9 位索引段加 12 位页内偏移，走表最多 3 次访存；x86 四级页表切 4 段、最多 4 次。级数就是每次 TLB 缺失的最小访存次数——这也是后面大页和 TLB 缓存值钱的原因。</span></p>',11)),(B(),r(o,null,{default:e(()=>[l(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20TLBM%5B%22TLB%20%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20W1%5B%22%E8%AF%BB%E6%A0%B9%E7%9B%AE%E5%BD%95%22%5D%0A%20%20W1%20--%3E%20W2%5B%22%E8%AF%BB%E4%B8%AD%E9%97%B4%E9%A1%B9%22%5D%0A%20%20W2%20--%3E%20LEAF%5B%22%E8%AF%BB%E5%8F%B6%E9%A1%B9%22%5D%0A%20%20LEAF%20--%3E%7C%22%E6%9C%89%E6%95%88%22%7C%20FILL%5B%22%E5%A1%AB%20TLB%EF%BC%8C%E9%87%8D%E6%94%BE%E8%AE%BF%E5%AD%98%22%5D%0A%20%20LEAF%20--%3E%7C%22%E6%97%A0%E6%95%88%22%7C%20PF%5B%22%E7%B2%BE%E7%A1%AE%E7%BC%BA%E9%A1%B5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t("p",null,"访问/脏位：硬件可在走表时置 A/D，避免内核事后扫表。本课承认这两位存在，不把原子置位的总线事务写完。",-1)),a[4]||(a[4]=t("h2",{id:"机制",tabindex:"-1"},[E("机制 "),t("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=t("p",null,"CPI 里 TLB 缺失代价 ≈ 级数 × 一次 cache 命中（理想）或 DRAM。与缺页的磁盘代价不在同一量级。硬件游走的访存必须绕过或正确处理「正在翻译的那条」的依赖，否则死锁——实现用独立的走表端口或不可再入的 MMU 缓冲。",-1)),(B(),r(o,null,{default:e(()=>[l(n,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E8%B5%B0%E8%A1%A8%E7%9A%84%E6%AF%8F%E4%B8%80%E6%AC%A1%E8%AE%BF%E5%AD%98%22%5D%20--%3E%20H1%5B%22L1%20%E5%91%BD%E4%B8%AD%EF%BC%9A%E4%B8%AA%E4%BD%8D%E6%95%B0%E5%91%A8%E6%9C%9F%22%5D%0A%20%20W%20--%3E%20H2%5B%22%E6%9C%AB%E7%BA%A7%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%EF%BC%9A%E6%95%B0%E5%8D%81%E5%91%A8%E6%9C%9F%22%5D%0A%20%20W%20--%3E%20D%5B%22%E8%90%BD%E5%88%B0%20DRAM%EF%BC%9A%E4%B8%A4%E7%99%BE%E5%91%A8%E6%9C%9F%E4%BB%A5%E4%B8%8A%22%5D%0A%20%20H1%20--%3E%20T%5B%22%E5%9B%9B%E7%BA%A7%20walk%20%E6%80%BB%E4%BB%A3%E4%BB%B7%E7%9B%B8%E5%B7%AE%E6%95%B0%E5%8D%81%E5%80%8D%22%5D%0A%20%20H2%20--%3E%20T%0A%20%20D%20--%3E%20T%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">死锁风险可以类比：查字典时遇到一个「生僻字」，词条又要查同一本字典才能读懂。若翻译硬件规定「必须先完成当前翻译才能发下一次访存」，就永远卡死；所以走表访问走绿色通道——独立端口、且本身不再触发翻译的物理访问。</span></p><p>多核下，另一核改页表时，硬件游走可能读到撕裂的中间指针；内核仍靠 TLB 射击与页表修改协议。ASID 是下一课，本课假定换进程会处理 TLB。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入反置页表走访、不讨论 nested paging / 二阶段翻译的完整状态机（虚拟机附录）。软件游走作为对照：内核可以做任意保护策略，热路径更慢。也不把走表当成 DMA：那些 load 对软件不可见。</p><p>后课默认：TLB 缺失由 MMU 硬件走多级表；只有叶无效才陷入。进程切换时如何避免全刷 TLB，是下一课 ASID/PCID。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>硬件游走让 TLB 缺失不陷入；真缺页才精确异常。</li><li>走表访存走 cache，代价随级数与是否命中变。</li><li>用地址空间标签避免切换全刷，是下一课。</li><li>出处：Hennessy and Patterson, <em>CA:AQA</em>；Patterson and Hennessy, <em>COD</em> RISC-V 翻译与页表。</li></ul>',7))])}const P=A(p,[["render",c]]);export{L as __pageData,P as default};
